// Zero-trust ingress: the caller is authenticated before anything is read.
// HMAC-SHA256 over the raw body, constant-time compared, with a replay window.
// A proposal that fails here never reaches the model.
const crypto = require('crypto');

const SECRET = $env.RFED_WEBHOOK_SECRET;
const MAX_SKEW_SECONDS = 300;

if (!SECRET) {
  throw new Error('RFED_WEBHOOK_SECRET is unset — refusing to accept unsigned proposals (fail closed)');
}

const out = [];
for (const item of $input.all()) {
  const headers = item.json.headers || {};
  const rawBody = item.json.body === undefined ? '' : (typeof item.json.body === 'string' ? item.json.body : JSON.stringify(item.json.body));
  const signature = headers['x-clearglass-signature'] || '';
  const timestamp = headers['x-clearglass-timestamp'] || '';

  if (!signature || !timestamp) {
    throw new Error('missing x-clearglass-signature / x-clearglass-timestamp');
  }

  const skew = Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp));
  if (!Number.isFinite(skew) || skew > MAX_SKEW_SECONDS) {
    throw new Error(`timestamp outside ${MAX_SKEW_SECONDS}s replay window`);
  }

  const expected = crypto.createHmac('sha256', SECRET).update(`${timestamp}.${rawBody}`).digest('hex');
  const a = Buffer.from(expected, 'utf8');
  const b = Buffer.from(String(signature), 'utf8');
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    throw new Error('signature mismatch — proposal rejected');
  }

  const payload = typeof item.json.body === 'string' ? JSON.parse(item.json.body) : item.json.body;
  out.push({ json: { ...payload, _raw_body: rawBody, _verified: true } });
}
return out;

// RFED record builder + governor.
// Mirrors bots/rfed_audit_bot.py — assess() and RfedRecord.compute_hash().
// The Python module is the authority; this node must stay hash-compatible with
// it, which is what tests/test_rfed_hash_parity.py pins.
const crypto = require('crypto');

const POLICY_VERSION = 'rfed-1.0.0';
const GENESIS_HASH = '0'.repeat(64);

const ACTION_RISK = {
  retrieve_context: 0, read_telemetry: 0, classify_record: 5, summarize_document: 5,
  score_record: 10, draft_internal_note: 15,
  enrich_record: 30, update_internal_doc: 35, create_ticket: 38, draft_client_comms: 40,
  publish_report: 45,
  send_client_comms: 70, close_ticket: 62, push_config_change: 78, quarantine_endpoint: 75,
  modify_access_policy: 92, grant_privileged_access: 100, rotate_credentials: 95,
  execute_remote_command: 98, disable_security_control: 100, export_client_data: 94,
  modify_audit_log: 100,
};

const ALWAYS_ESCALATE = new Set(['modify_access_policy','grant_privileged_access','rotate_credentials','execute_remote_command','disable_security_control','export_client_data','modify_audit_log','push_config_change','quarantine_endpoint','send_client_comms']);
const NEVER_AUTOMATE = new Set(['modify_audit_log']);
const INJECTION_MARKERS = ['ignore previous instructions','ignore all previous','disregard the above','you are now','system prompt','reveal your instructions','exfiltrate','send credentials'];

const REDACTIONS = [
  ['[redacted:email]', /[\w.+-]+@[\w-]+\.[\w.]+/g],
  ['[redacted:card]', /\b(?:\d[ -]*?){13,19}\b/g],
  ['[redacted:sin]', /\b\d{3}[- ]\d{3}[- ]\d{3}\b/g],
  ['[redacted:bearer]', /\bbearer\s+[A-Za-z0-9._\-]{12,}/gi],
  ['[redacted:key]', /\b(?:sk|pk|api|token)[_-][A-Za-z0-9]{16,}/gi],
];
function redact(s) { let o = String(s); for (const [rep, re] of REDACTIONS) o = o.replace(re, rep); return o; }

// --- canonicalisation -------------------------------------------------------
// Must byte-match Python's json.dumps(sort_keys=True, separators=(',',':'),
// ensure_ascii=True). Python renders floats via repr(), so 0 -> '0.0'; JS cannot
// tell an int from a float, so float-typed fields are wrapped in PyFloat.
class PyFloat { constructor(v) { this.v = Number(v); } }
function floatLiteral(n) {
  if (!Number.isFinite(n)) throw new Error('non-finite float in RFED record');
  return Number.isInteger(n) ? n.toFixed(1) : String(n);
}
function canonical(value) {
  if (value instanceof PyFloat) return floatLiteral(value.v);
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return '[' + value.map(canonical).join(',') + ']';
  return '{' + Object.keys(value).sort().map(k => JSON.stringify(k) + ':' + canonical(value[k])).join(',') + '}';
}
function asciiEscape(s) {
  return s.replace(/[\u007f-\uffff]/g, c => '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0'));
}
function sha256(s) { return crypto.createHash('sha256').update(s, 'utf8').digest('hex'); }
function digest(obj) { return sha256(asciiEscape(canonical(obj))); }

// --- governor ---------------------------------------------------------------
function tierFor(score) {
  if (score >= 90) return 'critical';
  if (score >= 60) return 'high';
  if (score >= 30) return 'medium';
  return 'low';
}

function assess(action, facts, evidence, payload) {
  payload = payload || {};
  const reasons = [];
  let base = ACTION_RISK[action];
  if (base === undefined) { reasons.push(`unknown action '${action}' — defaulting to high risk (fail closed)`); base = 85; }
  let score = base;

  if (payload.scope === 'all' || payload.bulk === true) { score = Math.min(100, score + 8); reasons.push('affects all managed assets / bulk operation'); }
  if (payload.outside_change_window === true) { score = Math.min(100, score + 6); reasons.push('executes outside the agreed change window'); }

  const ungrounded = !evidence.citations || evidence.citations.length === 0;
  if (ungrounded) { score = Math.min(100, score + 15); reasons.push('model cited no facts — output is ungrounded and cannot be audited'); }

  const lowConfidence = evidence.confidence < 0.75;
  if (lowConfidence) { score = Math.min(100, score + 12); reasons.push(`model confidence ${evidence.confidence.toFixed(2)} below threshold 0.75`); }

  const tainted = [];
  for (const f of facts) {
    if (f.trusted) continue;
    const hay = `${f.source} ${f.reference}`.toLowerCase();
    const hit = INJECTION_MARKERS.find(m => hay.includes(m));
    if (hit) tainted.push(`${f.source}:${hit}`);
  }
  if (tainted.length) { score = Math.min(100, score + 20); reasons.push(`possible prompt injection in untrusted facts: ${tainted.join(', ')}`); }

  const known = new Set(facts.map(f => f.reference));
  const dangling = (evidence.citations || []).filter(c => !known.has(c));
  if (dangling.length) { score = Math.min(100, score + 25); reasons.push(`citations not present in supplied facts: ${dangling.slice().sort().join(', ')}`); }

  const tier = tierFor(score);
  let requiresApproval = ['high','critical'].includes(tier) || ALWAYS_ESCALATE.has(action) || ungrounded || lowConfidence || tainted.length > 0 || dangling.length > 0;
  if (ALWAYS_ESCALATE.has(action)) reasons.push('action is in the always-escalate set (access / credentials / outbound)');

  let route;
  if (NEVER_AUTOMATE.has(action)) { route = 'blocked'; reasons.push('action is never automatable — ledger integrity is non-negotiable'); }
  else if (requiresApproval) { route = 'queued_for_approval'; reasons.push('hard gate enabled — cannot auto-execute'); }
  else { route = 'auto_executed'; reasons.push('auto-executable: reversible, grounded, low risk'); }

  return { score, tier, route, requires_approval: requiresApproval || route === 'blocked', reasons, approved_by: null, approved_at: null };
}

// --- build ------------------------------------------------------------------
const proposal = $('Verify Caller (HMAC)').first().json;
const headRow = $('Fetch Chain Head').all()[0];
const prevHash = (headRow && headRow.json && headRow.json.chain_hash) ? headRow.json.chain_hash : GENESIS_HASH;
const facts = $('Retrieve Grounding Facts').all().map(f => ({
  source: f.json.source,
  reference: f.json.reference,
  content_digest: f.json.content_digest,
  retrieved_at: f.json.retrieved_at,
  trusted: f.json.trusted !== false,
}));

const raw = $input.first().json;
let analysis = { finding: '', citations: [], confidence: 0 };
try {
  const text = (raw.content && raw.content[0] && raw.content[0].text) || '{}';
  analysis = { ...analysis, ...JSON.parse(text) };
} catch (e) {
  // Unparseable model output is a zero-confidence, uncited result. It will be
  // gated by the ungrounded + low-confidence signals rather than crashing.
  analysis = { finding: 'unparseable model output', citations: [], confidence: 0 };
}

const usage = raw.usage || {};
const evidence = {
  model_id: raw.model || $env.RFED_MODEL_ID,
  provider: 'anthropic',
  temperature: new PyFloat(0),
  max_tokens: 1024,
  prompt_digest: digest({ action: proposal.action, target: proposal.target, facts }),
  output_digest: digest(analysis),
  output_excerpt: redact(String(analysis.finding)).slice(0, 500),
  confidence: new PyFloat(analysis.confidence),
  citations: analysis.citations || [],
  input_tokens: usage.input_tokens || 0,
  output_tokens: usage.output_tokens || 0,
};

const decision = assess(proposal.action, facts, { citations: evidence.citations, confidence: Number(analysis.confidence) }, proposal.payload || {});

const body = {
  record_id: crypto.randomUUID(),
  occurred_at: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z'),
  policy_version: POLICY_VERSION,
  prev_hash: prevHash,
  request: {
    actor: 'n8n:rfed-audit-trail',
    workflow: proposal.workflow || 'client_zero_trust',
    action: proposal.action,
    target: proposal.target,
    intent: proposal.intent || '',
    correlation_id: proposal.correlation_id || '',
    input_digest: sha256(proposal._raw_body || ''),
  },
  facts,
  evidence,
  decision,
};

const chainHash = sha256(prevHash + asciiEscape(canonical(body)));

return [{ json: { ...body, evidence: { ...evidence, temperature: evidence.temperature.v, confidence: evidence.confidence.v }, chain_hash: chainHash } }];

