// Single response shape for every branch. The caller always learns the record
// id and the chain hash, so it can verify the decision independently.
const r = $('Build RFED Record').first().json;
return [{ json: {
  record_id: r.record_id,
  chain_hash: r.chain_hash,
  route: r.decision.route,
  tier: r.decision.tier,
  score: r.decision.score,
  requires_approval: r.decision.requires_approval,
  reasons: r.decision.reasons,
  executed: r.decision.route === 'auto_executed',
} }];
